  PATTERNS: [
    ["Could you ~?","Matinahoron nga hangyo: \"Puwede ba nimo…?\" Mas hinay kaysa \"Can you\"","Could you help me with this?","polite"],
    ["Would you mind ~ing?","Matinahoron kaayo nga hangyo: \"Okay ra ba nimo kon…?\" Ang tubag nga \"No\" nagpasabot nga mosugot ka","Would you mind closing the window?","polite"],
    ["Can I get ~?","Sa tindahan o restawran: \"Puwede mangayo og…?\" Pinakakasagaran sa sinultihan sa Amerika","Can I get a large latte?","polite"],
    ["I'd like ~","Matinahoron nga porma sa \"want\": \"Gusto unta ko og…\"","I'd like a window seat, please.","polite"],
    ["a / an + noun","Usa ka butang nga maihap ug bag-o pa nga gihisgotan. \"an\" kon vowel ang tingog sa sinugdanan","I have an idea.","articles"],
    ["the + noun","Ang butang nga pareho ninyong nahibaloan kon hain. Dili tanang \"ang\" kay \"the\"","Can you open the door?","articles"],
    ["I am / You are / She is","be verb: \"mao\", \"naa sa\" o kahimtang. Sa Bisaya walay pulong para niini","She is a nurse.","be"],
    ["Do you ~? / Does he ~?","Pangutana nga naay laing verb gawas sa be verb. \"does\" kon \"he\", \"she\" o \"it\" ang subject","Does he live here?","be"],
    ["don't / doesn't + base form","Negative sa mga verb gawas sa be verb: \"dili\" o \"wala\"","I don't eat meat.","be"],
    ["he / she / it + verb-s","Sa simple present tense, dugangi og -s ang verb kon \"he\", \"she\" o \"it\" ang subject","My sister works at a hospital.","be"],
    ["be + -ing form","Ang gibuhat karon mismo, o plano nga nahan-ay na sa dili madugay","I'm meeting Jake tonight.","tense"],
    ["verb-ed / irregular past form","Nahuman na nga panghitabo (went, ate, saw…). Mausab ang verb bisan naay \"gahapon\"","I went to Davao last week.","tense"],
    ["will + base form","Desisyon nga gihimo karon mismo, saad o tagna","I'll call you later.","tense"],
    ["be going to + base form","Plano nga gihunahuna na daan","I'm going to visit my parents this weekend.","tense"],
    ["Have you ever ~?","Pangutana bahin sa kasinatian: \"Naka-… na ka?\"","Have you ever tried lechon?","tense"],
    ["in + bulan / tuig","Taas nga panahon. Sa Bisaya, \"sa\" ra","My birthday is in June.","prep"],
    ["on + adlaw / petsa","Usa ka piho nga adlaw","The party is on Saturday.","prep"],
    ["at + oras / lugar","Eksaktong oras o usa ka piho nga lugar","Let's meet at 7 at the station.","prep"],
    ["How about ~ing?","Sugyot: \"Unsa kaha kon…?\"","How about getting lunch together?","smalltalk"],
    ["So do I / Neither do I","Pag-uyon: \"Ako sab\" (positive / negative). Kaswal: \"Me too\" / \"Me neither\"","I love this song. / So do I.","smalltalk"],
    ["verb + it + adverb","Kon pronoun ang object sa phrasal verb, ibutang kini sa tunga","Can you turn it down?","phrasal"],
    ["look forward to + -ing form","Preposition ang \"to\" dinhi, mao nga -ing form ang mosunod","I'm looking forward to hearing from you.","phrasal"],
    ["It's + oras","Pagsulti sa oras: basaha ang oras unya ang minuto, sa Iningles nga numero","It's ten fifteen.","numbers"],
    ["I'm writing to ~","Sa unang sentence sa email, isulti ang tuyo","I'm writing to confirm our meeting.","email"],
    ["Let me know if ~","\"Pahibaloa ko kon…\": kasagarang panapos sa email","Let me know if you need anything else.","email"]
  ],
